package com.luixifer.autostudio;
import android.app.*;
import android.content.*;
import android.os.*;
import android.net.Uri;
import android.provider.MediaStore;
import android.widget.*;
import android.view.View;
import org.json.*;
import java.io.*;
import java.util.*;

/** Mobile-first project editor. Long operations share the existing IO executor. */
public class DirectorActivity extends Activity {
 private DirectorStore store;private String projectId;private JSONObject project;private LinearLayout body;private TextView status;private EditText title;private boolean busy=false;private final Handler handler=new Handler();
 private void task(Work work,Runnable done){busy=true;status.setText("Trabajando… Mantén abierta la aplicación durante la subida o descarga.");AutoStudioApp.IO.execute(()->{try{work.run();runOnUiThread(()->{busy=false;done.run();});}catch(Exception e){runOnUiThread(()->{busy=false;status.setText(e.getMessage());Ui.error(this,e.getMessage());});}});}
 interface Work{void run()throws Exception;}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);store=new DirectorStore(this);projectId=getIntent().getStringExtra("project_id");show();}
 private void show(){try{body=Ui.scroll(this,Ui.root(this,projectId==null?"AutoStudio Director":"Tu documental"));status=Ui.para(body,"LAB · Montaje en la nube. Sin publicación en YouTube.");
  if(projectId==null){Ui.button(body,"Conectar GitHub / ajustes",2100,false).setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));Ui.para(body,"Director necesita permiso Contents: lectura y escritura para adjuntos, además de Actions. No hay claves dentro de la APK. Los archivos se envían a un borrador de GitHub Release en tu repositorio; no uses material confidencial.");
   Ui.button(body,"Crear documental",2101,true).setOnClickListener(v->{EditText name=new EditText(this);name.setText("Las luces de Hessdalen");new AlertDialog.Builder(this).setTitle("Nombre del proyecto").setView(name).setPositiveButton("Crear",(d,w)->{try{open(store.create(name.getText().toString()));}catch(Exception e){Ui.error(this,e.getMessage());}}).setNegativeButton("Cancelar",null).show();});
   Ui.button(body,"Restaurar proyecto desde ZIP",2116,false).setOnClickListener(v->pick("application/zip",12));
   for(String id:store.projects()){JSONObject p=store.load(id);Ui.button(body,p.optString("title"),View.generateViewId(),false).setOnClickListener(v->open(id));}return;}
  project=store.load(projectId);title=new EditText(this);title.setText(project.getString("title"));title.setHint("Título");body.addView(title);title.setOnFocusChangeListener((v,focus)->{if(!focus)saveTitle();});
  Spinner format=new Spinner(this);format.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Horizontal · 1920 × 1080","Vertical · 1080 × 1920"}));format.setSelection(project.getString("format").equals("vertical")?1:0);body.addView(format);format.setOnItemSelectedListener(new SimpleSelection(){public void onItemSelected(android.widget.AdapterView<?> a,View v,int pos,long x){try{project.put("format",pos==0?"horizontal":"vertical");store.save(projectId,project);}catch(Exception e){Ui.error(DirectorActivity.this,e.getMessage());}}});
  Spinner voice=new Spinner(this);voice.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Álex · español · voz provisional","Santa · español · voz provisional","Dora · voz anterior"}));String vn=project.getJSONObject("voice").optString("voice");voice.setSelection(vn.equals("em_santa")?1:vn.equals("ef_dora")?2:0);body.addView(voice);voice.setOnItemSelectedListener(new SimpleSelection(){public void onItemSelected(android.widget.AdapterView<?> a,View v,int pos,long x){try{project.put("voice",new JSONObject().put("mode","kokoro").put("voice",new String[]{"em_alex","em_santa","ef_dora"}[pos]));store.save(projectId,project);}catch(Exception e){Ui.error(DirectorActivity.this,e.getMessage());}}});
  Ui.para(body,"Guion: un párrafo por escena; separa con una línea en blanco. Para capítulos, usa un bloque independiente que comience con #. Primero importa el guion; después adjunta los recursos a cada escena.");
  Ui.button(body,"Importar guion TXT",2102,false).setOnClickListener(v->pick("text/plain",10));Ui.button(body,"Escribir / pegar guion",2103,false).setOnClickListener(v->{EditText text=new EditText(this);text.setMinLines(5);new AlertDialog.Builder(this).setTitle("Guion por escenas").setView(text).setPositiveButton("Importar",(d,w)->replaceScript(text.getText().toString())).setNegativeButton("Cancelar",null).show();});
  Ui.button(body,"Añadir música propia WAV / MP3",2104,false).setOnClickListener(v->pick("audio/*",11));
  if(project.has("music"))Ui.button(body,"Quitar música del montaje",2105,false).setOnClickListener(v->{try{project.remove("music");store.save(projectId,project);show();}catch(Exception e){Ui.error(this,e.getMessage());}});
  JSONArray chapters=project.getJSONArray("chapters");for(int c=0;c<chapters.length();c++){JSONObject chapter=chapters.getJSONObject(c);Ui.para(body,chapter.optString("title","Capítulo "+(c+1)));JSONArray scenes=chapter.getJSONArray("scenes");for(int s=0;s<scenes.length();s++){final int ci=c,si=s;JSONObject scene=scenes.getJSONObject(s);LinearLayout card=Ui.card(body);String text=scene.optString("narration");Ui.para(card,(s+1)+" · "+text.substring(0,Math.min(95,text.length()))+(scene.has("media")?"\nRecurso adjunto":"\nFalta imagen o vídeo"));Ui.button(card,"Editar escena y recursos",View.generateViewId(),false).setOnClickListener(v->startActivity(new Intent(this,Scene.class).putExtra("project_id",projectId).putExtra("chapter",ci).putExtra("scene",si)));LinearLayout row=new LinearLayout(this);card.addView(row);for(int delta:new int[]{-1,1}){Button b=new Button(this);b.setText(delta<0?"Subir escena":"Bajar escena");row.addView(b,new LinearLayout.LayoutParams(0,-2,1));b.setEnabled(si+delta>=0&&si+delta<scenes.length());b.setOnClickListener(v->{try{JSONObject a=scenes.getJSONObject(si),other=scenes.getJSONObject(si+delta);scenes.put(si,other);scenes.put(si+delta,a);store.save(projectId,project);show();}catch(Exception e){Ui.error(this,e.getMessage());}});}}}
  Ui.para(body,"Máximo 200 MiB por envío. Los clips deben cubrir la locución o tener bucle explícito. La voz decide las duraciones; no se calculan por número de palabras. Material propio: confirma tus derechos al generar.");
  Ui.button(body,"Guardar copia del proyecto ZIP",2117,false).setOnClickListener(v->{if(busy)return;saveTitle();Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"AutoStudio-Director-"+projectId.substring(0,8)+".zip");startActivityForResult(i,13);});
  Ui.button(body,"Generar documental",2106,true).setOnClickListener(v->generate());Ui.button(body,"Consultar y recuperar resultado",2107,false).setOnClickListener(v->refresh());
  File job=new File(store.folder(projectId),"job.json");if(job.isFile())status.setText("Solicitud guardada: "+DirectorStore.read(job).optString("request_id")+". Pulsa Consultar para recuperar el resultado.");
 }catch(Exception e){Ui.error(this,e.getMessage());}}
 private void open(String id){startActivity(new Intent(this,DirectorActivity.class).putExtra("project_id",id));}
 private void saveTitle(){try{if(title!=null){project.put("title",title.getText().toString());store.save(projectId,project);}}catch(Exception e){Ui.error(this,e.getMessage());}}
 private void replaceScript(String text){try{JSONArray chapters=DirectorStore.parseScript(text);new AlertDialog.Builder(this).setTitle("Importar escenas").setMessage("Se reemplazará la lista de escenas. Los archivos adjuntos anteriores se conservan en el proyecto.").setPositiveButton("Importar",(d,w)->{try{project.put("chapters",chapters);store.save(projectId,project);show();}catch(Exception e){Ui.error(this,e.getMessage());}}).setNegativeButton("Cancelar",null).show();}catch(Exception e){Ui.error(this,e.getMessage());}}
 private void pick(String mime,int request){if(busy)return;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType(mime).addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,request);}
 @Override public void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;final Uri uri=data.getData();task(()->{if(req==12){String restored=store.restore(uri);runOnUiThread(()->open(restored));}else if(req==13){File zip=store.bundle(projectId);try(InputStream in=new FileInputStream(zip);OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("No se puede escribir la copia");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}}else if(req==10){try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Guion no accesible");String text=DirectorStore.text(in,200_000);runOnUiThread(()->replaceScript(text));}}else if(req==11){String name=store.importFile(projectId,uri,"music");project.put("music",new JSONObject().put("path",name).put("gain",.12).put("rights",DirectorStore.ownRights()));store.save(projectId,project);}},()->{if(req!=10)show();else status.setText("Guion leído: confirma la importación.");});}
 private void generate(){if(busy)return;saveTitle();new AlertDialog.Builder(this).setTitle("Producir en GitHub").setMessage("Confirmo que tengo derechos de uso sobre el texto, imágenes, clips, voz y música. Se enviarán a un borrador de Release en Luixifer/AutoStudio, sin YouTube. No es un almacén confidencial. Mantén la APK abierta durante la subida. Si falla, consulta la misma solicitud antes de enviar otra.").setPositiveButton("Confirmar y generar",(d,w)->task(()->{File existing=new File(store.folder(projectId),"job.json");if(existing.isFile()){JSONObject old=DirectorStore.read(existing);if(!old.optBoolean("terminal"))throw new IOException("Ya existe una solicitud pendiente. Consulta su estado; no se duplicará automáticamente.");}DirectorGitHub client=new DirectorGitHub(new CredentialStore(this).load());File bundle=store.bundle(projectId);String id=DirectorStore.id();JSONObject job=new JSONObject().put("request_id",id).put("terminal",false).put("stage","SENDING").put("bundle_sha256",DirectorStore.sha(bundle));DirectorStore.write(existing,job);client.start(bundle,id);job.put("stage","RUNNING");DirectorStore.write(existing,job);},()->{status.setText("Producción enviada. Puede continuar en la nube al cerrar la APK. Consulta su estado para recuperar el documental.");})).setNegativeButton("Cancelar",null).show();}
 private void refresh(){if(busy)return;task(()->{File dir=store.folder(projectId),jobFile=new File(dir,"job.json");if(!jobFile.isFile())throw new IOException("Todavía no hay una solicitud");JSONObject job=DirectorStore.read(jobFile);String id=job.getString("request_id");DirectorGitHub client=new DirectorGitHub(new CredentialStore(this).load());JSONObject release=client.release(id),r=client.result(release);if(r==null){runOnUiThread(()->status.setText("Resultado pendiente. Si la subida o el envío fallaron, revisa el borrador y Actions antes de iniciar otra solicitud."));return;}if(!r.getString("request_id").equals(id))throw new IOException("Resultado de otra solicitud");if(!r.getString("status").equals("completed")){job.put("terminal",true).put("stage","FAILED");DirectorStore.write(jobFile,job);throw new IOException(r.optString("error","La producción ha fallado; consulta los registros"));}File video=new File(dir,"documental-REVISION.mp4");client.download(release,r,video);job.put("terminal",true).put("stage","READY").put("result",r);DirectorStore.write(jobFile,job);runOnUiThread(()->{status.setText("MP4 descargado y SHA-256 verificado. Duración: "+r.optDouble("duration")+" segundos.");Ui.button(body,"Reproducir documental",2110,true).setOnClickListener(v->startActivity(new Intent(this,Preview.class).putExtra("project_id",projectId)));});},()->{});}
 @Override public void onResume(){super.onResume();if(store!=null&&!busy&&projectId!=null)show();}
 @Override public void onStop(){handler.removeCallbacksAndMessages(null);super.onStop();}
 public abstract static class SimpleSelection implements android.widget.AdapterView.OnItemSelectedListener{public void onNothingSelected(android.widget.AdapterView<?> a){}}
 public static class Scene extends Activity {
  DirectorStore store;String id;JSONObject p,s;EditText text,trim;TextView status;int chapter,index;boolean importing=false;
  @Override public void onCreate(Bundle saved){super.onCreate(saved);try{store=new DirectorStore(this);id=getIntent().getStringExtra("project_id");chapter=getIntent().getIntExtra("chapter",0);index=getIntent().getIntExtra("scene",0);p=store.load(id);s=p.getJSONArray("chapters").getJSONObject(chapter).getJSONArray("scenes").getJSONObject(index);LinearLayout body=Ui.scroll(this,Ui.root(this,"Editar escena "+(index+1)));status=Ui.para(body,"Recursos originales conservados; ajustes solo del montaje.");text=new EditText(this);text.setText(s.getString("narration"));text.setMinLines(4);body.addView(text);
    if(s.has("media")){JSONObject m=s.getJSONObject("media");Ui.para(body,m.getString("path"));if(m.getString("kind").equals("image")){android.graphics.BitmapFactory.Options o=new android.graphics.BitmapFactory.Options();o.inJustDecodeBounds=true;File file=new File(store.folder(id),m.getString("path"));android.graphics.BitmapFactory.decodeFile(file.toString(),o);o.inSampleSize=Math.max(1,Math.max(o.outWidth,o.outHeight)/600);o.inJustDecodeBounds=false;ImageView image=new ImageView(this);image.setImageBitmap(android.graphics.BitmapFactory.decodeFile(file.toString(),o));image.setScaleType(ImageView.ScaleType.FIT_CENTER);body.addView(image,new LinearLayout.LayoutParams(-1,Ui.dp(this,220)));}
      else {trim=new EditText(this);trim.setHint("Recortar desde segundo");trim.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);trim.setText(String.valueOf(m.optDouble("trim_start",0)));body.addView(trim);CheckBox loop=new CheckBox(this);loop.setText("Repetir clip si es más corto que la voz");loop.setChecked(m.optBoolean("loop"));body.addView(loop);loop.setOnCheckedChangeListener((v,checked)->{try{m.put("loop",checked);persist();}catch(Exception e){Ui.error(this,e.getMessage());}});}}
    Ui.button(body,"Adjuntar imagen o MP4",2201,true).setOnClickListener(v->pickMedia(20));Ui.button(body,"Usar mi locución WAV / MP3",2202,false).setOnClickListener(v->pickMedia(21));if(s.has("voice"))Ui.button(body,"Volver a voz sintética",2203,false).setOnClickListener(v->{try{s.remove("voice");persist();recreate();}catch(Exception e){Ui.error(this,e.getMessage());}});
    Spinner transition=new Spinner(this);transition.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Corte limpio","Disolución suave · 0,4 s"}));transition.setSelection(s.optJSONObject("transition")!=null&&s.getJSONObject("transition").optString("type").equals("dissolve")?1:0);body.addView(transition);transition.setOnItemSelectedListener(new SimpleSelection(){public void onItemSelected(android.widget.AdapterView<?> a,View v,int pos,long key){try{s.put("transition",new JSONObject().put("type",pos==0?"cut":"dissolve").put("seconds",pos==0?0:.4));persist();}catch(Exception e){Ui.error(Scene.this,e.getMessage());}}});
    Ui.button(body,"Guardar escena",2204,true).setOnClickListener(v->{try{persist();finish();}catch(Exception e){Ui.error(this,e.getMessage());}});Ui.para(body,"Los MP4 se normalizan sin deformar y su sonido se silencia. La locución importada se alinea con Whisper CPU: si el texto no coincide, la producción se detendrá para revisión.");
   }catch(Exception e){Ui.error(this,e.getMessage());}}
  void persist()throws Exception{s.put("narration",text.getText().toString());if(trim!=null)s.getJSONObject("media").put("trim_start",Double.parseDouble(trim.getText().toString()));store.save(id,p);}
  void pickMedia(int code){if(importing)return;try{persist();Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType(code==21?"audio/*":"*/*").addCategory(Intent.CATEGORY_OPENABLE);if(code==20)i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/jpeg","image/png","image/webp","video/mp4"});startActivityForResult(i,code);}catch(Exception e){Ui.error(this,e.getMessage());}}
  @Override public void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;importing=true;status.setText("Importando recurso…");AutoStudioApp.IO.execute(()->{try{String name=store.importFile(id,data.getData(),req==21?"voice":"visual");if(req==21)s.put("voice",new JSONObject().put("mode","file").put("path",name));else s.put("media",new JSONObject().put("kind",name.endsWith(".mp4")?"video":"image").put("path",name).put("rights",DirectorStore.ownRights()).put("fit","contain").put("source_audio",false));store.save(id,p);runOnUiThread(()->{importing=false;recreate();});}catch(Exception e){runOnUiThread(()->{importing=false;Ui.error(this,e.getMessage());});}});}
 }
 public static class Preview extends Activity {
  @Override public void onCreate(Bundle saved){super.onCreate(saved);try{String id=getIntent().getStringExtra("project_id");File file=new File(new DirectorStore(this).folder(id),"documental-REVISION.mp4");LinearLayout body=Ui.scroll(this,Ui.root(this,"Revisar documental"));VideoView video=new VideoView(this);body.addView(video,new LinearLayout.LayoutParams(-1,Ui.dp(this,300)));MediaController controls=new MediaController(this);controls.setAnchorView(video);video.setMediaController(controls);video.setVideoURI(Uri.fromFile(file));video.setOnPreparedListener(p->video.start());video.setOnErrorListener((p,w,e)->{Ui.error(this,"El reproductor no pudo decodificar el MP4");return true;});Ui.button(body,"Guardar en Descargas",2301,true).setOnClickListener(v->{AutoStudioApp.IO.execute(()->{try{if(Build.VERSION.SDK_INT<29)throw new IOException("Guardar en Descargas requiere Android 10 o superior en este laboratorio");ContentValues values=new ContentValues();values.put(MediaStore.Downloads.DISPLAY_NAME,"AutoStudio-Director-"+id.substring(0,8)+".mp4");values.put(MediaStore.Downloads.MIME_TYPE,"video/mp4");values.put(MediaStore.Downloads.IS_PENDING,1);Uri uri=getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException("No se pudo crear la descarga");try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("No se pudo guardar");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}catch(Exception e){getContentResolver().delete(uri,null,null);throw e;}values.clear();values.put(MediaStore.Downloads.IS_PENDING,0);getContentResolver().update(uri,values,null,null);runOnUiThread(()->new AlertDialog.Builder(this).setMessage("Documental guardado en Descargas").setPositiveButton("Aceptar",null).show());}catch(Exception e){runOnUiThread(()->Ui.error(this,e.getMessage()));}});});}catch(Exception e){Ui.error(this,e.getMessage());}}
 }
}
